<template>
  <div class="page-shell bib-page">
    <PageHero title="文献计量" description="基于知识库真实文献数据分析研究趋势、热点主题、核心机构与作者，为遗址公园相关研究提供结构化线索。" :image="portalHero" compact>
      <template #actions><el-button plain @click="loadData"><el-icon><Refresh /></el-icon>刷新分析</el-button><el-button plain @click="exportNotice"><el-icon><Download /></el-icon>导出说明</el-button></template>
    </PageHero>

    <section class="filter-surface bib-filter"><div><span>分析范围</span><strong>当前知识库全部文献</strong></div><div><span>时间范围</span><strong>{{ yearRange }}</strong></div><div><span>数据来源</span><strong>平台知识库</strong></div><el-button type="primary" :loading="loading" @click="loadData">重新计算</el-button></section>
    <StatusState v-if="loading" type="loading" title="正在计算文献计量结果" />
    <StatusState v-else-if="error" type="error" title="文献计量数据加载失败" :description="error" action-label="重新加载" @action="loadData" />
    <StatusState v-else-if="!data||!data.total_docs" type="empty" title="暂无可分析文献" description="知识库入库文献后将显示真实计量结果。" />
    <template v-else>
      <div class="bib-stat-grid"><article v-for="item in statItems" :key="item.label"><span :class="item.tone"><el-icon><component :is="item.icon" /></el-icon></span><div><small>{{ item.label }}</small><strong>{{ item.value }}</strong><p>{{ item.meta }}</p></div></article></div>
      <section class="bib-main-grid"><div class="chart-card chart-wide"><div class="section-card__header"><div><h2>发文量趋势</h2><p>按知识库文献年份汇总。</p></div></div><div ref="trendChart" class="chart-canvas"></div></div><div class="chart-card"><div class="section-card__header"><div><h2>文献类型分布</h2><p>当前文献类型构成。</p></div></div><div ref="typeChart" class="chart-canvas"></div></div><div class="chart-card"><div class="section-card__header"><div><h2>研究热点主题 Top10</h2><p>由关键词共现权重计算。</p></div></div><ol class="topic-ranking"><li v-for="(item,index) in topKeywords" :key="item.name"><span>{{ index+1 }}</span><strong>{{ item.name }}</strong><i><b :style="{width:`${item.percent}%`}"></b></i><small>{{ item.value }}</small></li></ol></div></section>
      <section class="bib-secondary-grid"><div class="chart-card"><div class="section-card__header"><div><h2>研究热点共现图谱</h2><p>展示关键词之间的共现强度。</p></div></div><div ref="cooccurChart" class="chart-canvas tall"></div></div><div class="chart-card"><div class="section-card__header"><div><h2>作者合作网络</h2><p>基于当前作者关系数据。</p></div></div><div v-if="data.author_network?.nodes?.length" ref="authorChart" class="chart-canvas tall"></div><StatusState v-else type="empty" title="暂无作者合作关系" /></div></section>
      <section class="bib-bottom-grid"><div class="chart-card"><div class="section-card__header"><div><h2>机构发文量</h2><p>当前机构统计 Top15。</p></div></div><div ref="instChart" class="chart-canvas tall"></div></div><div class="section-card cited-panel"><div class="section-card__header"><div><h2>高被引文献</h2><p>按真实被引次数排序。</p></div></div><div v-if="data.top_cited?.length" class="cited-list"><article v-for="(item,index) in data.top_cited.slice(0,10)" :key="item.title"><span>{{ index+1 }}</span><div><strong>{{ item.title }}</strong><p>{{ item.year||'年份未知' }}</p></div><small>被引 {{ item.citations||0 }}</small></article></div><StatusState v-else type="empty" title="暂无引用数据" /></div><aside class="section-card insight-panel"><div class="section-card__header"><div><h2>研究洞察</h2><p>从当前计量结果中直接提炼。</p></div></div><div v-for="item in insights" :key="item.title"><span><el-icon><TrendCharts /></el-icon></span><div><strong>{{ item.title }}</strong><p>{{ item.text }}</p></div></div></aside></section>
    </template>
  </div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import * as echarts from 'echarts'
import { Document, TrendCharts, Connection, User, OfficeBuilding, View } from '@element-plus/icons-vue'
import api from '@/utils/api'
import PageHero from '@/components/portal/PageHero.vue'
import StatusState from '@/components/common/StatusState.vue'
import portalHero from '@/assets/images/portal-hero.webp'
const data=ref(null);const loading=ref(true);const error=ref('');const trendChart=ref();const typeChart=ref();const cooccurChart=ref();const authorChart=ref();const instChart=ref();const charts=[];let observer
const years=computed(()=>(data.value?.yearly_trend||[]).map(item=>Number(item.year)).filter(Number.isFinite));const yearRange=computed(()=>years.value.length?`${Math.min(...years.value)} — ${Math.max(...years.value)}`:'暂无年份');const topKeywords=computed(()=>{const keywords=data.value?.keyword_cooccurrence?.keywords||[];const matrix=data.value?.keyword_cooccurrence?.matrix||[];const items=keywords.map((name,index)=>({name,value:(matrix[index]||[]).reduce((sum,value)=>sum+Number(value||0),0)})).sort((a,b)=>b.value-a.value).slice(0,10);const max=items[0]?.value||1;return items.map(item=>({...item,percent:Math.max(5,item.value/max*100)}))});const statItems=computed(()=>[{label:'文献总量',value:Number(data.value.total_docs||0).toLocaleString('zh-CN'),meta:'知识库当前文献',icon:Document,tone:'blue'},{label:'引用关系',value:Number(data.value.total_citations||0).toLocaleString('zh-CN'),meta:'当前引用记录',icon:Connection,tone:'green'},{label:'知识关联',value:Number(data.value.total_relations||0).toLocaleString('zh-CN'),meta:'语义关联关系',icon:TrendCharts,tone:'violet'},{label:'作者节点',value:Number(data.value.author_network?.nodes?.length||0),meta:'合作网络作者',icon:User,tone:'orange'},{label:'机构数量',value:Number(data.value.institution_stats?.length||0),meta:'已识别机构',icon:OfficeBuilding,tone:'blue'},{label:'文献类型',value:Number(data.value.doc_type_distribution?.length||0),meta:'已识别类型',icon:View,tone:'cyan'}]);const insights=computed(()=>{const peak=[...(data.value?.yearly_trend||[])].sort((a,b)=>b.count-a.count)[0];const topType=[...(data.value?.doc_type_distribution||[])].sort((a,b)=>b.count-a.count)[0];return[{title:'研究趋势',text:peak?`${peak.year} 年发文量最高，共 ${peak.count} 篇。`:'暂无年度趋势数据。'},{title:'热点主题',text:topKeywords.value[0]?`当前共现权重最高的关键词为“${topKeywords.value[0].name}”。`:'暂无关键词共现数据。'},{title:'主要文献类型',text:topType?`${topType.type}数量最多，共 ${topType.count} 篇。`:'暂无类型分布数据。'}]})
onMounted(loadData);onBeforeUnmount(()=>{observer?.disconnect();charts.forEach(chart=>chart.dispose())})
async function loadData(){loading.value=true;error.value='';try{data.value=(await api.get('/knowledge/bibliometrics',{silent:true})).data;loading.value=false;await nextTick();renderAll()}catch(e){error.value=e.response?.data?.detail||'请检查知识库与计量服务后重试。';loading.value=false}}
function makeChart(el){if(!el)return null;const chart=echarts.init(el);charts.push(chart);observer||=new ResizeObserver(()=>charts.forEach(item=>item.resize()));observer.observe(el);return chart}
function renderAll(){charts.splice(0).forEach(chart=>chart.dispose());if(!data.value?.total_docs)return;const palette=['#2563eb','#22c55e','#7c3aed','#f59e0b','#06b6d4'];makeChart(trendChart.value)?.setOption({color:['#2563eb'],tooltip:{trigger:'axis'},grid:{top:18,right:24,bottom:34,left:45},xAxis:{type:'category',data:data.value.yearly_trend.map(item=>item.year),axisLine:{lineStyle:{color:'#e7eaf0'}}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#eef1f5'}}},series:[{type:'line',data:data.value.yearly_trend.map(item=>item.count),smooth:true,symbolSize:7,lineStyle:{width:3},areaStyle:{color:'rgba(37,99,235,.08)'}}]});makeChart(typeChart.value)?.setOption({color:palette,tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['46%','70%'],center:['50%','44%'],data:data.value.doc_type_distribution.map(item=>({name:item.type,value:item.count}))}]});const keywords=data.value.keyword_cooccurrence?.keywords||[];const matrix=data.value.keyword_cooccurrence?.matrix||[];if(keywords.length)makeChart(cooccurChart.value)?.setOption({tooltip:{formatter:param=>`${keywords[param.data[0]]} × ${keywords[param.data[1]]}：${param.data[2]}`},grid:{top:18,right:24,bottom:72,left:78},xAxis:{type:'category',data:keywords,axisLabel:{rotate:40,fontSize:9}},yAxis:{type:'category',data:keywords,axisLabel:{fontSize:9}},visualMap:{min:0,max:Math.max(...matrix.flat(),1),calculable:true,orient:'horizontal',left:'center',bottom:4,inRange:{color:['#eff6ff','#93c5fd','#2563eb']}},series:[{type:'heatmap',data:matrix.flatMap((row,i)=>row.map((value,j)=>[j,i,value]))}]});if(data.value.author_network?.nodes?.length)makeChart(authorChart.value)?.setOption({color:palette,tooltip:{},series:[{type:'graph',layout:'force',data:data.value.author_network.nodes.map(node=>({name:node.name,symbolSize:30})),links:(data.value.author_network.edges||[]).slice(0,80).map(edge=>({source:edge.source,target:edge.target})),roam:true,force:{repulsion:220,edgeLength:[80,180]},label:{show:true,fontSize:9,position:'bottom'},lineStyle:{color:'#cbd5e1'}}]});const institutions=(data.value.institution_stats||[]).slice(0,15);makeChart(instChart.value)?.setOption({color:['#3b82f6'],tooltip:{trigger:'axis'},grid:{top:12,right:24,bottom:26,left:92},xAxis:{type:'value',splitLine:{lineStyle:{color:'#eef1f5'}}},yAxis:{type:'category',data:institutions.map(item=>item.name).reverse(),axisLabel:{fontSize:10}},series:[{type:'bar',barMaxWidth:18,data:institutions.map(item=>item.count).reverse(),itemStyle:{borderRadius:[0,7,7,0]}}]})}
function exportNotice(){ElMessage.info('当前后端尚未提供文献计量报告导出接口。')}
</script>

<style scoped lang="scss">
.bib-filter{display:grid;grid-template-columns:repeat(3,1fr) auto;align-items:center;gap:16px}.bib-filter>div{display:grid;padding-right:16px;border-right:1px solid var(--border)}.bib-filter span{color:var(--text-tertiary);font-size:10px}.bib-filter strong{margin-top:4px;font-size:13px}.bib-stat-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}.bib-stat-grid article{padding:16px;display:flex;align-items:center;gap:10px;border:1px solid var(--border);border-radius:14px;background:#fff;box-shadow:var(--shadow-soft)}.bib-stat-grid article>span{width:40px;height:40px;display:grid;place-items:center;flex:0 0 auto;border-radius:12px;color:var(--brand-600);background:var(--brand-50)}.bib-stat-grid article>span.green{color:#16a34a;background:#f0fdf4}.bib-stat-grid article>span.violet{color:#7c3aed;background:#f5f3ff}.bib-stat-grid article>span.orange{color:#ea580c;background:#fff7ed}.bib-stat-grid article>span.cyan{color:#0891b2;background:#ecfeff}.bib-stat-grid article div{min-width:0;display:grid}.bib-stat-grid small{color:var(--text-tertiary);font-size:9px}.bib-stat-grid strong{font-size:20px}.bib-stat-grid p{margin:3px 0 0;color:var(--text-tertiary);font-size:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.bib-main-grid{display:grid;grid-template-columns:1.3fr .75fr .75fr;gap:14px}.bib-secondary-grid,.bib-bottom-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.bib-bottom-grid{grid-template-columns:1fr 1.2fr .75fr}.topic-ranking{display:grid;gap:7px;list-style:none}.topic-ranking li{display:grid;grid-template-columns:18px 1fr 1.4fr 28px;align-items:center;gap:7px;font-size:10px}.topic-ranking li>span{width:18px;height:18px;display:grid;place-items:center;border-radius:50%;color:var(--brand-600);background:var(--brand-50)}.topic-ranking i{height:4px;border-radius:999px;background:#edf2f7;overflow:hidden}.topic-ranking b{display:block;height:100%;border-radius:999px;background:var(--brand-500)}.topic-ranking small{text-align:right;color:var(--text-tertiary)}.cited-panel,.insight-panel{padding:20px}.cited-list{display:grid}.cited-list article{padding:9px 0;display:grid;grid-template-columns:22px 1fr auto;align-items:center;gap:8px;border-bottom:1px solid var(--border)}.cited-list article>span{color:var(--brand-600);font-weight:700}.cited-list article div{min-width:0}.cited-list strong{display:block;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cited-list p{margin:3px 0 0;color:var(--text-tertiary);font-size:8px}.cited-list small{color:var(--text-secondary);font-size:9px}.insight-panel>div:not(.section-card__header){display:flex;gap:8px;padding:11px 0;border-bottom:1px solid var(--border)}.insight-panel>div>span{width:30px;height:30px;display:grid;place-items:center;flex:0 0 auto;border-radius:9px;color:var(--brand-600);background:var(--brand-50)}.insight-panel strong{font-size:10px}.insight-panel p{margin:4px 0 0;color:var(--text-secondary);font-size:9px;line-height:1.5}@media(max-width:1200px){.bib-stat-grid{grid-template-columns:repeat(3,1fr)}.bib-main-grid{grid-template-columns:1fr 1fr}.bib-main-grid>div:first-child{grid-column:1/-1}.bib-bottom-grid{grid-template-columns:1fr 1fr}.insight-panel{grid-column:1/-1}}@media(max-width:760px){.bib-filter{grid-template-columns:1fr 1fr}.bib-filter .el-button{grid-column:1/-1}.bib-stat-grid{display:flex;overflow-x:auto}.bib-stat-grid article{min-width:170px}.bib-main-grid,.bib-secondary-grid,.bib-bottom-grid{grid-template-columns:1fr}.bib-main-grid>div:first-child,.insight-panel{grid-column:auto}}
</style>
